# Mock Wasmer classes for testing without actual WASM compilation
class MockMemory:
    def __init__(self, size_pages=1):
        self._buffer = bytearray(size_pages * 65536) # 64KB per page
        self.uint8_view = lambda ptr: self._buffer[ptr:] # Simplified view

    @property
    def buffer(self):
        return self._buffer

