        # Simulate WASM agent behavior based on self.behavior
        if self.behavior == "success":
            output = {"code_coverage": 85.5}
        elif self.behavior == "failure":
            output = {"code_coverage": 75.0}
        elif self.behavior == "malformed":
            output = {"coverage": "eighty"} # Wrong key and type
        elif self.behavior == "crash":
            raise RuntimeError("WASM trap: simulated memory access out of bounds")
        elif self.behavior == "infinite_loop":
            # Simulate an infinite loop by just not returning within a reasonable time
            # This will be caught by an external timeout mechanism
            import time
            time.sleep(100) # Simulate long execution
            output = {"code_coverage": 0.0} # Should not be reached
        elif self.behavior == "malformed_json":
            # Return invalid JSON string
            output_str = "{not_json"
            self._write_to_mock_memory(output_str.encode('utf-8'))
            return 0 # Return pointer to start of output
        elif self.behavior == "misleading_metrics":
            output = {"code_coverage": 999.9} # Valid JSON, but logically misleading
        elif self.behavior == "wasi_attempt":
            # Simulate a WASI call attempt that would fail if WASI isn't provided
            # In a real scenario, this would be an InstantiationError or a trap
            # For this mock, we'll raise a specific error that the sandbox can catch.
            raise WasmerWasiError("WASI call attempted without host support")
        else:
            output = {}

        output_bytes = json.dumps(output).encode('utf-8')
        self._write_to_mock_memory(output_bytes)
        return 0 # Return pointer to start of output

    def _write_to_mock_memory(self, data: bytes):
        # Write data to mock memory, assuming it fits at ptr 0 for simplicity
        self.memory.buffer[:len(data)] = data
        # Ensure null termination for _read_from_memory
        if len(data) < len(self.memory.buffer):
            self.memory.buffer[len(data)] = 0

